<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#18372e"><title>پنل مدیریت | دکتر مصطفی خویی</title><style>
:root{--g:#203a32;--g2:#315747;--gold:#b99a70;--bg:#f3f5f1;--muted:#78847b;--line:#e5ebe3}*{box-sizing:border-box}body{margin:0;background:var(--bg);font-family:Tahoma,Arial,sans-serif;color:#263b31}button,input,textarea,select{font:inherit}button{cursor:pointer}.login-wrap{min-height:100vh;display:grid;place-items:center;padding:20px}.login{width:min(420px,100%);background:#fff;border:1px solid var(--line);border-radius:24px;padding:30px;box-shadow:0 25px 70px #203a3215}.login h1{font-size:22px}.login p,.muted{color:var(--muted);font-size:12px;line-height:2}.field{display:grid;gap:7px;margin:13px 0;font-size:12px}.field input,.field textarea,.field select{width:100%;border:1px solid #dce5da;border-radius:11px;padding:12px;background:#fff;outline:none}.btn{border:0;border-radius:11px;padding:12px 17px;background:var(--g);color:#fff;font-weight:700}.btn.gold{background:var(--gold);color:#26382f}.btn.light{background:#eef3ed;color:var(--g)}.btn.danger{background:#fff0ed;color:#a3463b}.full{width:100%}.error{color:#a13d32;background:#fff0ed;padding:10px;border-radius:10px;font-size:12px}.shell{display:none;min-height:100vh}.side{position:fixed;right:0;top:0;bottom:0;width:245px;background:linear-gradient(180deg,#18372e,#254b3d);color:white;padding:24px 16px;z-index:5}.brand{font-size:17px;font-weight:bold;padding:8px 12px 28px}.brand small{display:block;font-size:10px;color:#c2d0c6;margin-top:8px}.navbtn{display:flex;width:100%;border:0;background:transparent;color:#dce8df;padding:13px 14px;border-radius:11px;text-align:right;margin:4px 0;font-size:13px}.navbtn.active,.navbtn:hover{background:#ffffff19;color:#fff}.side-bottom{position:absolute;bottom:20px;right:16px;left:16px}.main{margin-right:245px;padding:28px;max-width:1600px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px;gap:12px}.top h1{font-size:24px;margin:0}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:15px}.stat,.panel{background:#fff;border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:0 8px 25px #203a3208}.stat small{color:var(--muted);font-size:11px}.stat b{display:block;font-size:25px;margin-top:12px;color:var(--g)}.panel{margin-top:18px;overflow:auto}.panel h2{font-size:17px;margin:0 0 16px}.table{width:100%;border-collapse:collapse;min-width:650px}.table th,.table td{padding:13px 10px;border-bottom:1px solid var(--line);text-align:right;font-size:12px;vertical-align:middle}.table th{color:var(--muted);font-weight:600;background:#fafbf9}.actions{display:flex;gap:7px;flex-wrap:wrap}.toolbar{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:14px}.toolbar input{padding:11px;border:1px solid var(--line);border-radius:10px;min-width:220px}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 15px}.formgrid .wide{grid-column:1/-1}.modal{position:fixed;inset:0;background:#10241dcc;display:none;place-items:center;padding:15px;z-index:10}.modal.show{display:grid}.modalbox{background:white;width:min(620px,100%);max-height:90vh;overflow:auto;padding:24px;border-radius:20px}.thumb{width:48px;height:48px;object-fit:cover;border-radius:9px;background:#eef2ed}.pill{display:inline-block;padding:5px 9px;border-radius:30px;background:#edf4ec;color:#456b4b;font-size:10px}.empty{padding:30px;text-align:center;color:var(--muted)}@media(max-width:900px){.side{width:75px;padding:15px 8px}.brand{font-size:0;padding:10px 0}.brand:after{content:'دخ';font-size:18px}.brand small,.navbtn span,.side-bottom .label{display:none}.navbtn{justify-content:center;font-size:18px;padding:14px 5px}.side-bottom{right:8px;left:8px}.main{margin-right:75px;padding:18px}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.main{padding:13px}.top h1{font-size:18px}.cards{gap:9px}.stat{padding:13px}.stat b{font-size:19px}.formgrid{grid-template-columns:1fr}.formgrid .wide{grid-column:auto}.toolbar{align-items:stretch;flex-direction:column}.toolbar input{width:100%}}

/* Mobile admin layout refinement — scoped to admin panel only */
@media(max-width:700px){
  html,body{max-width:100%;overflow-x:hidden}
  .side{
    position:sticky;top:0;bottom:auto;right:auto;width:100%;height:auto;
    min-height:0;padding:10px 12px 9px;z-index:20;
    display:flex;flex-wrap:wrap;align-items:center;gap:5px;
    box-shadow:0 8px 22px #10241d22
  }
  .brand{
    flex:1 0 100%;font-size:15px;padding:2px 5px 7px;
    display:flex;align-items:center;justify-content:space-between
  }
  .brand:after{content:"پنل مدیریت";font-size:10px;font-weight:400;color:#c2d0c6}
  .brand small{display:block;font-size:10px;margin:0}
  .navbtn{
    flex:1 1 calc(25% - 5px);width:auto;min-width:0;min-height:42px;
    justify-content:center;align-items:center;gap:5px;
    padding:9px 5px;margin:0;border:1px solid #ffffff12;
    border-radius:10px;font-size:12px;white-space:nowrap
  }
  .navbtn span,.side-bottom .label{display:inline}
  .side-bottom{
    position:static;inset:auto;flex:1 0 100%;
    display:flex;gap:6px;margin-top:2px
  }
  .side-bottom .navbtn{flex:1}
  .main{margin:0;max-width:none;width:100%;padding:17px 13px 28px}
  .top{align-items:flex-start;flex-wrap:wrap;margin-bottom:16px}
  .top h1{font-size:19px;line-height:1.7}
  .cards{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
  .stat,.panel{border-radius:15px}
  .stat{padding:14px;min-width:0}
  .stat small{font-size:10px}
  .stat b{font-size:19px;overflow-wrap:anywhere}
  .panel{padding:14px;margin-top:13px;overflow-x:auto}
  .panel h2{font-size:15px}
  .toolbar{gap:9px}
  .toolbar input{min-width:0;width:100%}
  .toolbar .btn{width:100%}
  .table{min-width:620px}
  .table th,.table td{padding:11px 9px;font-size:11px}
  .actions{min-width:120px}
  .actions .btn{padding:9px 11px;font-size:11px}
  .modal{padding:9px;align-items:center}
  .modalbox{width:100%;max-height:calc(100dvh - 18px);padding:17px;border-radius:16px}
  .modalbox .toolbar{flex-direction:row;align-items:center}
  .modalbox .toolbar .btn{width:auto}
  .field{font-size:12px}
  .field input,.field textarea,.field select{font-size:16px;min-height:44px}
  .login-wrap{padding:16px}
  .login{padding:24px 20px;border-radius:20px}
}
@media(max-width:390px){
  .side{padding:8px}
  .brand{font-size:14px}
  .brand small{font-size:9px}
  .navbtn{font-size:11px;gap:3px;padding:8px 3px;min-height:40px}
  .main{padding:13px 10px 24px}
  .top h1{font-size:17px}
  .cards{gap:8px}
  .stat{padding:11px}
  .stat b{font-size:17px}
  .pill{font-size:9px}
}
@media(min-width:701px) and (max-width:900px){
  .side{width:205px;padding:20px 12px}
  .brand{font-size:15px}
  .navbtn{font-size:12px}
  .main{margin-right:205px;padding:22px}
  .cards{grid-template-columns:repeat(2,minmax(0,1fr))}
}
</style></head><body>
<div class="login-wrap" id="loginView"><form class="login" id="loginForm"><div style="font-size:30px">✥</div><h1>ورود به پنل مدیریت</h1><p>مدیریت فروشگاه و سفارش‌های دکتر مصطفی خویی</p><label class="field">نام کاربری<input name="username" autocomplete="username" required></label><label class="field">رمز عبور<input name="password" type="password" autocomplete="current-password" required></label><div id="loginError"></div><button class="btn full" type="submit">ورود امن به پنل</button><p style="text-align:center">دسترسی ویژه مدیر سایت</p></form></div>
<div class="shell" id="app"><aside class="side"><div class="brand">مدیریت فروشگاه<small>دکتر مصطفی خویی</small></div><button class="navbtn active" data-page="dashboard">▦ <span>داشبورد</span></button><button class="navbtn" data-page="products">▣ <span>محصولات</span></button><button class="navbtn" data-page="categories">▤ <span>دسته‌بندی‌ها</span></button><button class="navbtn" data-page="orders">▧ <span>سفارش‌ها</span></button><div class="side-bottom"><button class="navbtn" id="logout">↪ <span>خروج از پنل</span></button><a class="navbtn" href="../index.html">⌂ <span>بازگشت به سایت</span></a></div></aside><main class="main"><div class="top"><h1 id="pageTitle">داشبورد</h1><span class="pill">اتصال امن مدیریت</span></div><div id="content"></div></main></div>
<div class="modal" id="modal"><div class="modalbox"><div class="toolbar"><h2 id="modalTitle">افزودن محصول</h2><button class="btn light" id="closeModal">بستن</button></div><form id="productForm"><input type="hidden" name="id"><input type="hidden" name="image"><div class="formgrid"><label class="field">نام محصول<input name="name" required maxlength="180"></label><label class="field">دسته‌بندی<select name="category_id" id="productCategory"></select></label><label class="field">قیمت (تومان)<input name="price" type="number" min="0" required></label><label class="field">موجودی<input name="stock" type="number" min="0" required value="0"></label><label class="field wide">توضیحات<textarea name="description" rows="4"></textarea></label><label class="field wide">تصویر محصول (JPG/PNG/WEBP، حداکثر ۴ مگابایت)<input id="imageFile" type="file" accept="image/jpeg,image/png,image/webp"></label><div class="wide" id="imagePreview"></div><label class="field"><span><input name="active" type="checkbox" checked style="width:auto"> محصول فعال باشد</span></label></div><button class="btn" type="submit">ذخیره محصول</button><div id="productError"></div></form></div></div>
<script>
let csrf='';const $=s=>document.querySelector(s),content=$('#content');async function api(action,opts={}){let h=opts.headers||{};if(csrf)h['X-CSRF-Token']=csrf;let r=await fetch('../api/index.php?action='+action,{credentials:'same-origin',...opts,headers:h});let j=await r.json().catch(()=>({error:'پاسخ سرور قابل خواندن نیست'}));if(!r.ok)throw Error(j.error||'خطای سرور');return j}async function init(){let x=await fetch('../api/index.php?action=csrf',{credentials:'same-origin'}).then(r=>r.json());csrf=x.csrf;if(x.loggedIn){$('#loginView').style.display='none';$('#app').style.display='block';show('dashboard')}}$('#loginForm').onsubmit=async e=>{e.preventDefault();try{let d=Object.fromEntries(new FormData(e.target));let x=await api('login',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(d)});csrf=x.csrf;$('#loginView').style.display='none';$('#app').style.display='block';show('dashboard')}catch(err){$('#loginError').innerHTML='<div class="error">'+esc(err.message)+'</div>'}};function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function money(n){return Number(n||0).toLocaleString('fa-IR')+' تومان'}function title(t){$('#pageTitle').textContent=t}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===b));show(b.dataset.page)});async function show(page){try{if(page==='dashboard')await dashboard();if(page==='products')await products();if(page==='categories')await categories();if(page==='orders')await orders()}catch(e){content.innerHTML='<div class="error">'+esc(e.message)+'</div>'}}
async function dashboard(){title('داشبورد');let d=await api('dashboard');content.innerHTML='<div class="cards">'+[['کل محصولات',d.stats.products],['کل سفارش‌ها',d.stats.orders],['سفارش جدید',d.stats.new_orders],['فروش پرداخت‌شده',money(d.stats.sales)]].map(x=>'<div class="stat"><small>'+x[0]+'</small><b>'+x[1]+'</b></div>').join('')+'</div><section class="panel"><h2>آخرین سفارش‌ها</h2>'+table(['کد سفارش','مشتری','مبلغ','وضعیت','تاریخ'],d.recent.map(o=>[o.order_code,o.customer_name,money(o.total),status(o.status),o.created_at]))+'</section>'}
function table(head,rows){return '<table class="table"><thead><tr>'+head.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="8" class="empty">موردی ثبت نشده است</td></tr>')+'</tbody></table>'}function status(s){return ({new:'جدید',processing:'در حال پردازش',sent:'ارسال شده',completed:'تکمیل شده',cancelled:'لغو شده'})[s]||s}
let productCache=[];async function products(){title('مدیریت محصولات');let d=await api('products');productCache=d.products;content.innerHTML='<div class="panel"><div class="toolbar"><input id="productSearch" placeholder="جست‌وجوی محصول"><button class="btn" id="addProduct">＋ افزودن محصول</button></div><div id="productTable"></div></div>';renderProductTable();$('#productSearch').oninput=renderProductTable;$('#addProduct').onclick=()=>openProduct();}function renderProductTable(){let q=$('#productSearch').value.toLowerCase();let a=productCache.filter(p=>p.name.toLowerCase().includes(q));$('#productTable').innerHTML=table(['تصویر','نام','دسته‌بندی','قیمت','موجودی','وضعیت','عملیات'],a.map(p=>['<img class="thumb" src="../'+esc(p.image||'assets/lavender-product.jpg')+'">',esc(p.name),esc(p.category||'—'),money(p.price),p.stock,p.active?'<span class="pill">فعال</span>':'غیرفعال','<div class="actions"><button class="btn light" onclick="editProduct('+p.id+')">ویرایش</button><button class="btn danger" onclick="delProduct('+p.id+')">حذف</button></div>']))}async function loadCats(){return (await api('categories')).categories}async function openProduct(p=null){let cats=await loadCats();$('#productCategory').innerHTML='<option value="">بدون دسته‌بندی</option>'+cats.map(c=>'<option value="'+c.id+'">'+esc(c.name)+'</option>').join('');let f=$('#productForm');f.reset();f.elements.id.value=p?.id||'';f.elements.image.value=p?.image||'';f.elements.name.value=p?.name||'';f.elements.description.value=p?.description||'';f.elements.price.value=p?.price||0;f.elements.stock.value=p?.stock||0;f.elements.category_id.value=p?.category_id||'';f.elements.active.checked=p?p.active===1:true;$('#imagePreview').innerHTML=p?.image?'<img class="thumb" src="../'+esc(p.image)+'">':'';$('#modalTitle').textContent=p?'ویرایش محصول':'افزودن محصول';$('#productError').innerHTML='';$('#modal').classList.add('show')}window.editProduct=id=>openProduct(productCache.find(p=>p.id==id));window.delProduct=async id=>{if(!confirm('محصول حذف شود؟'))return;try{await api('product-delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});await products()}catch(e){alert(e.message)}};$('#closeModal').onclick=()=>$('#modal').classList.remove('show');$('#imageFile').onchange=async e=>{if(!e.target.files[0])return;try{let fd=new FormData();fd.append('image',e.target.files[0]);let d=await api('upload',{method:'POST',body:fd});$('#productForm').elements.image.value=d.path;$('#imagePreview').innerHTML='<img class="thumb" src="../'+esc(d.path)+'">'}catch(err){$('#productError').innerHTML='<div class="error">'+esc(err.message)+'</div>'}};$('#productForm').onsubmit=async e=>{e.preventDefault();let f=e.target,d=Object.fromEntries(new FormData(f));d.active=f.elements.active.checked?1:0;d.id=Number(d.id||0);try{await api('product-save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});$('#modal').classList.remove('show');await products()}catch(err){$('#productError').innerHTML='<div class="error">'+esc(err.message)+'</div>'}}
async function categories(){title('مدیریت دسته‌بندی‌ها');let d=await loadCats();content.innerHTML='<div class="panel"><form id="catForm" class="toolbar"><input name="name" required placeholder="نام دسته‌بندی جدید"><button class="btn">افزودن دسته‌بندی</button></form><div id="catTable"></div></div>';$('#catTable').innerHTML=table(['نام دسته‌بندی','عملیات'],d.map(c=>[esc(c.name),'<button class="btn danger" onclick="delCat('+c.id+')">حذف</button>']));$('#catForm').onsubmit=async e=>{e.preventDefault();try{await api('category-save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:new FormData(e.target).get('name')})});categories()}catch(err){alert(err.message)}}}window.delCat=async id=>{if(confirm('دسته حذف شود؟ محصولات آن بدون دسته‌بندی باقی می‌مانند.')){await api('category-delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});categories()}};
async function orders(){title('مدیریت سفارش‌ها');let d=await api('orders');content.innerHTML='<div class="panel"><div class="toolbar"><input id="orderSearch" placeholder="جست‌وجوی کد، نام یا تلفن"></div><div id="orderTable"></div></div>';function draw(){let q=$('#orderSearch').value;let rows=d.orders.filter(o=>(o.order_code+o.customer_name+o.phone).includes(q));$('#orderTable').innerHTML=table(['کد','مشتری و تماس','اقلام','مبلغ','وضعیت سفارش','پرداخت','ثبت‌شده','عملیات'],rows.map(o=>[esc(o.order_code),esc(o.customer_name)+'<br>'+esc(o.phone)+'<br>'+esc(o.address),esc(o.items||''),money(o.total),'<select id="s'+o.id+'"><option value="new">جدید</option><option value="processing">در حال پردازش</option><option value="sent">ارسال شده</option><option value="completed">تکمیل شده</option><option value="cancelled">لغو شده</option></select>','<select id="p'+o.id+'"><option value="unpaid">پرداخت نشده</option><option value="paid">پرداخت شده</option><option value="refunded">بازپرداخت</option></select>',esc(o.created_at),'<button class="btn light" onclick="saveOrder('+o.id+')">ذخیره وضعیت</button>']));rows.forEach(o=>{$('#s'+o.id).value=o.status;$('#p'+o.id).value=o.payment_status})}$('#orderSearch').oninput=draw;draw();window.saveOrder=async id=>{try{await api('order-update',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,status:$('#s'+id).value,payment_status:$('#p'+id).value})});alert('وضعیت سفارش ذخیره شد')}catch(e){alert(e.message)}}}$('#logout').onclick=async()=>{try{await api('logout',{method:'POST'})}finally{location.reload()}};init().catch(e=>$('#loginError').textContent='اتصال به سرور برقرار نشد. '+e.message);
</script></body></html>